  declarations: [AppComponent],
  imports: [BrowserModule, SharedModule],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }
```
In this example, we're importing the `SharedModule` and adding it to the `imports` array. This will make the `MyComponent` available for use in the `AppComponent`.

