Here's a pulsing, sweetheart red heart fractal using p5.js and WebGL:

```javascript
let angle = 0;
let heartRadius = 100;
let detail = 5;
let numSides = 7;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(DEGREES);
}

function draw() {
  background(0);
  translate(0, 0, -200);
  rotateX(angle);
  rotateY(angle);
  drawHeart(0, 0, 0);
  angle += 0.5;
}

function drawHeart(cx, cy, cz) {
  let segment = TWO_PI / numSides;
  let subDetail = detail * 0.5;
  push();
  translate(cx, cy, cz);
  stroke(255, 0, 0, 255);
  fill(255, 0, 0, 128);
  noFill();
  beginShape();
  for (let a = 0; a < TWO_PI; a += segment) {
    let sx = cos(a) * heartRadius;
    let sy = sin(a) * heartRadius;
    letqx = cos(a + segment / 4) * heartRadius * subDetail;
    letqy = sin(a + segment / 4) * heartRadius * subDetail;
    vertex(sx, sy, 0);
    let sx2 = cos(a + segment / 2) * heartRadius * subDetail;
    let sy2 = sin(a + segment / 2) * heartRadius * subDetail;
    vertex(sx2, sy2, 0);
  }
  let sx3 = cos(0) * heartRadius;
  let sy3 = sin(0) * heartRadius;
  let qx3 = cos(segment / 4) * heartRadius * subDetail;
  let qy3 = sin(segment / 4) * heartRadius * subDetail;
  vertex(sx3, sy3, 0);
  endShape(CLOSE);
  pop();
}
```

This code creates a 3D heart fractal by recursively drawing smaller hearts with decreasing detail. The fractal is animated by rotating the entire scene.

