Here's a basic React autocomplete component that doesn't rely on any third-party packages. This component uses the `useState` and `useEffect` hooks to manage the state of the autocomplete suggestions and the user's input.

```jsx
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ classes, suggestions, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const filterSuggestions = () => {
      const matchingSuggestions = suggestions.filter((suggestion) => {
        return suggestion
          .toLowerCase()
          .includes(inputValue.toLowerCase());
      });
      setSuggestionsList(matchingSuggestions);
    };

    if (inputValue) {
      filterSuggestions();
    } else {
      setSuggestionsList([]);
    }
  }, [inputValue, suggestions]);

  const handleInputValueChange = (event) => {
    const { value } = event.target;
    setInputValue(value);
    setActiveSuggestionIndex(-1);
  };

  const handleInputFocus = () => {
    setActiveSuggestionIndex(-1);
  };

  const handleInputBlur = () => {
    // Reset the active suggestion index when the input loses focus
    setActiveSuggestionIndex(-1);
  };

  const handleSuggestionClick = (suggestion) => {
    setInputValue(suggestion);
    onSelect(suggestion);
  };

  const handleArrowDown = () => {
    if (activeSuggestionIndex + 1 < suggestionsList.length) {
      setActiveSuggestionIndex(activeSuggestionIndex + 1);
    }
  };

  const handleArrowUp = () => {
    if (activeSuggestionIndex > 0) {
      setActiveSuggestionIndex(activeSuggestionIndex - 1);
    } else if (suggestionsList.length > 0) {
      setActiveSuggestionIndex(suggestionsList.length - 1);
    }
  };

  const handleEnterPress = (event) => {
    if (event.key === 'Enter') {
      handleSuggestionClick(suggestionsList[activeSuggestionIndex]);
    }
  };

  const styles = {
    autocomplete: {
      position: 'absolute',
      background: 'white',
      width: '100%',
      display: 'flex',
      flexWrap: 'wrap',
      justifyContent: 'space-between',
      padding: '2px',
      borderRadius: '5px',
      boxShadow: '0 0 10px rgba(0,0,0,0.2)',
    },
    description: {
      fontSize: '1.1em',
    },
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputValueChange}
        onFocus={handleInputFocus}
        onBlur={handleInputBlur}
        onKeyPress={handleEnterPress}
        placeholder="Start typing..."
        className={classes.input}
