    public void transform(jvmtiAGETransformer transformer, jvmtiTaggedObject info) {
        // Get the class definition
        jvmtiEnhancedClassFile file = (jvmtiEnhancedClassFile) info;

        // Create a new method
        jvmtiPrimitiveType[] paramTypes = new jvmtiPrimitiveType[0];
        jvmtiPrimitiveType returnType = jvmtiPrimitiveType.Java_Void;
        String methodName = "myStaticMethod";
