```
class Password {
  constructor(password, options = {}) {
    this.password = password;
    this.options = options;
    this.generateDigest = options.generateDigest || 'sha256';
    this.passwordFormat = options.passwordFormat || 'complex';
  }

  generate() {
    const passwordFormat = this.passwordFormat;
    const passwordLength = this.options.passwordLength || 12;
    const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-={}:';
    let password = '';

    switch (passwordFormat) {
      case 'simple':
        password = this.password;
        break;
      case 'complex':
        for (let i = 0; i < passwordLength; i++) {
          password += characters.charAt(Math.floor(Math.random() * characters.length));
        }
        break;
      default:
        throw new Error(`Invalid password format: ${passwordFormat}`);
    }

    return password;
  }

  hash() {
    const hash = crypto.createHash(this.generateDigest);
    return hash.update(this.generate()).digest('hex');
  }

  verify(password, hash) {
    const newPassword = this.generate();
    const newHash = this.hash();

    return hash === newHash;
  }
}
```
