        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        // Create a list to store the received packets
        List<Packet> packets = new ArrayList<>();

        // Loop until the user stops the program
        while (true) {
            // Wait for a selection event
            selector.select();

            // Iterate over the selection keys
            for (SelectionKey key : selector.selectedKeys()) {
                // Check if the key is for an accepted connection
                if (key.isAcceptable()) {
                    // Get the accepted socket channel
                    SocketChannel socketChannel = serverSocketChannel.accept();
                    socketChannel.configureBlocking(false);

                    // Register the socket channel for reading
                    socketChannel.register(selector, SelectionKey.OP_READ);

                    // Print a message to indicate that a new connection was accepted
                    System.out.println("New connection accepted");
                } else if (key.isReadable()) {
                    // Get the readable socket channel
                    SocketChannel socketChannel = (SocketChannel) key.channel();

                    // Read the packet from the socket channel
                    ByteBuffer buffer = ByteBuffer.allocate(1024);
                    int bytesRead = socketChannel.read(buffer);
                    buffer.flip();

                    // Create a new packet object
                    Packet packet = new Packet(buffer.array(), bytesRead);

                    // Add the packet to the list
                    packets.add(packet);

                    // Print a message to indicate that a packet was received
                    System.out.println("Packet received");
                }
            }

            // Clear the selection keys
            selector.selectedKeys().clear();
        }
    }
}

