TicTacToe.prototype HumanitiesMove = function() {
    let moves = this.getAllMoves();
    if (moves.length === 9) return Math.floor(Math.random() * 9);
    let bestMove = 0;
    let bestScore = -Infinity;
    for (let i = 0; i < moves.length; i++) {
        let move = moves[i];
        this.board[move[0]][move[1]] = this.playerTurn;
        let score = this.minimax(0);
        this.board[move[0]][move[1]] = "";
        if (score > bestScore) {
            bestMove = move;
            bestScore = score;
        }
    }
    return bestMove;
}

TicTacToe.prototype.minimax = function(depth, isMaximizing) {
    if (this.winner() !== "") {
        if (this.winner() === this.playerTurn) return 1;
        if (this.winner() !== this.playerTurn) return -1;
        return 0;
    }
    if (this boardIsFull()) return 0;
    let scores = [];
    let moves = this.getAllMoves();
    for (let i = 0; i < moves.length; i++) {
        let move = moves[i];
        this.board[move[0]][move[1]] = this.playerTurn;
        let score = this.minimax(depth + 1, !isMaximizing);
        this.board[move[0]][move[1]] = "";
        scores.push(score);
    }
    if (isMaximizing) {
        return Math.max(...scores);
    } else {
        return Math.min(...scores);
    }
}

TicTacToe.prototype.getAllMoves = function() {
    let moves = [];
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            if (this.board[i][j] === "") {
                let move = [i, j];
                moves.push(move);
            }
        }
    }
    return moves;
}

TicTacToe.prototype.boardIsFull = function() {
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            if (this.board[i][j] === "") return false;
        }
    }
    return true;
}

